    ('a0aec173-1e85-4832-8be6-99ebcdfeb247'::uuid, 'period_start', '-400', '1', 'fields-wd1-2026-09-26d-s015-rollback:a0aec173-1e85-4832-8be6-99ebcdfeb247:period_start', 'rollback of fields-wd1-2026-09-26d-s015: period_start ''1'' restored on Tsarskyi Kurgan (Royal Kurgan)', '[{"source": "https://en.wikipedia.org/wiki/Royal_Kurgan", "url": "https://en.wikipedia.org/wiki/Royal_Kurgan", "quote": "from the 4th century BC, is one of the most impressive tumuli (", "outcome": "found"}, {"source": "https://www.encyclopediaofukraine.com/display.asp?linkpath=pages\\T\\S\\Tsarskyikurhan.htm", "url": "https://www.encyclopediaofukraine.com/display.asp?linkpath=pages\\T\\S\\Tsarskyikurhan.htm", "quote": "A 4th-century BC Bosporan Kingdom burial mound located southwest of Kerch", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0410)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the Encyclopedia of Ukraine both date the Royal Kurgan to the 4th century BC; in 500 BC - 1 AD, not 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('a0b08567-cd34-467a-bd6d-428196261423'::uuid, 'period_name', NULL, '500 - 1000 AD', 'fields-wd1-2026-09-26d-s015-rollback:a0b08567-cd34-467a-bd6d-428196261423:period_name', 'rollback of fields-wd1-2026-09-26d-s015: period_name ''500 - 1000 AD'' restored on Kuhikugu', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
