    ('a0c043a9-fc02-49d8-93e8-39100e5ed8c7'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26d-s015-rollback:a0c043a9-fc02-49d8-93e8-39100e5ed8c7:period_name', 'rollback of fields-wd1-2026-09-26d-s015: period_name ''3000 - 1500 BC'' restored on Uplistsikhe', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1000) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a0c043a9-fc02-49d8-93e8-39100e5ed8c7'::uuid, 'period_start', '-1000', '-2000', 'fields-wd1-2026-09-26d-s015-rollback:a0c043a9-fc02-49d8-93e8-39100e5ed8c7:period_start', 'rollback of fields-wd1-2026-09-26d-s015: period_start ''-2000'' restored on Uplistsikhe', '[{"source": "https://en.wikipedia.org/wiki/Uplistsikhe", "url": "https://en.wikipedia.org/wiki/Uplistsikhe", "quote": "The earliest traces of human presence in Uplistsikhe date back to the end of the 2nd millennium BC.", "outcome": "found"}, {"source": "https://travelgraph.ge/en/uplistsikhe-cave-town", "url": "https://travelgraph.ge/en/uplistsikhe-cave-town", "quote": "It is one of the oldest urban settlements in Georgia: its history begins in the first millennium BC, and in antiquity it served as an important trading and religious centre.", "outcome": "found"}, {"source": "https://iberogeorgia.com/en/destination/uplistsikhe-cave-town/", "url": "https://iberogeorgia.com/en/destination/uplistsikhe-cave-town/", "quote": "Uplistsikhe began to be inhabited around the first millennium BC, during the Iron Age, and grew to become one of the political and religious centres of the ancient Iberian kingdom of", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia puts the earliest human presence at Uplistsikhe at the end of the 2nd millennium BC, and two independent Georgian travel guides put the start of its history and habitation in the first millennium BC (Iron Age); the attested start is thus around 1000 BC, in the 1500 - 500 BC bucket, not c. 2000 BC as stored.", "value_page": null}]'::jsonb),
    ('a0d4a5ea-fb2c-435c-a8b0-a6e12143b007'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26d-s015-rollback:a0d4a5ea-fb2c-435c-a8b0-a6e12143b007:period_name', 'rollback of fields-wd1-2026-09-26d-s015: period_name ''4500 - 3000 BC'' restored on Little Kit''s Coty House', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
