    ('a0f4690e-06d0-457b-92da-40207bfeec25'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26d-s015-rollback:a0f4690e-06d0-457b-92da-40207bfeec25:period_name', 'rollback of fields-wd1-2026-09-26d-s015: period_name ''3000 - 1500 BC'' restored on Old Winchester Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('a0f4690e-06d0-457b-92da-40207bfeec25'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26d-s015-rollback:a0f4690e-06d0-457b-92da-40207bfeec25:period_start', 'rollback of fields-wd1-2026-09-26d-s015: period_start ''-3000'' restored on Old Winchester Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0119)", "decision": "clear", "status": "MISSING", "reasoning": "The sources disagree on what starts the site and when: Wikipedia dates barrows to 2100-750 BCE (no second source) and the fort to 600-300 BCE, while UK Hillfort Lidar dates the fort to circa 500 BC, in another bucket.", "value_page": null}]'::jsonb),
